/**
 * @param {number} n
 * @param {number[]} nums
 * @param {number} maxDiff
 * @param {number[][]} queries
 * @return {number[]}
 */
var pathExistenceQueries = function(n, nums, maxDiff, queries) {
    const arr = Array.from({ length: n }, (_, i) => i);

    arr.sort((a, b) => nums[a] - nums[b]);

    const groups = Array(n).fill(0);
    const dp = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => i === j ? 0 : -1));
    let group = 0;

    for (let i = 1; i < n; i++) {
        if (nums[arr[i]] - nums[arr[i - 1]] > maxDiff) {
            group++;
        }
        groups[arr[i]] = group;

        let curr = nums[arr[i]];
        let dist = 1;

        for (let j = i - 1; j >= 0; j--) {
            if (groups[arr[j]] !== group) break;

            if (curr - nums[arr[j]] > maxDiff) {
                dist++;
                curr = nums[arr[j + 1]];
            }

            dp[arr[i]][arr[j]] = dist;
        }
    }

    const res = [];

    for (const [u, v] of queries) {
        res.push(Math.max(dp[u][v], dp[v][u]));
    }

    return res;
};

